Lemma ts_ld_nextW : forall {R : Type} A (HW : WF A) s (m0 : word -> option byte) ws x mt (k : word -> M R) P,
  RepW A m0 ws (ms_mem s) -> WIN s -> a_meta A x = Some mt -> wfree_range ws (x + moff FNext) 8 -> 0 <= mt_next mt ->
